/**
 * R-1839 — owner drawings / capital introduced: reads and the three money RPCs
 * (migration 20261024142228_r1839_owner_equity.sql). Every write goes through an RPC that
 * also moves the bank / cash line, so the account balance and the equity entry never drift.
 *
 * Read and written through an untyped client: the table and functions are newer than
 * database.types.ts (shared, regenerated by the manager after the migration lands).
 */
"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { SupabaseClient } from "@supabase/supabase-js";
import { toast } from "sonner";

import { createClient } from "@/lib/supabase/client";
import { useCurrentUser } from "@/lib/hooks/useCurrentUser";
import { toastError } from "@/lib/errors/toast-error";
import type { OwnerEquityKind, OwnerEquityMovement } from "@/lib/accounting/owner-equity";

const untyped = () => createClient() as unknown as SupabaseClient;

export const OWNER_EQUITY_KEY = ["owner_equity_movements"] as const;

/**
 * The table is not there yet (code deployed before migration 20261024142228): there are no
 * entries to count, so the Balance Sheet can still show — every other failed read stays an error.
 */
export function isOwnerEquityTableMissing(err: unknown): boolean {
  const m = err instanceof Error ? err.message : String(err ?? "");
  return /owner_equity_movements/.test(m) && /(does not exist|could not find|schema cache)/i.test(m);
}

/** owner_equity_movements.partner_id is not there yet (R-1847 migration not applied). */
export function isPartnerIdMissing(message: string): boolean {
  return /partner_id/.test(message) && /(does not exist|could not find|schema cache)/i.test(message);
}

/** Every entry of the company, newest first. A failed read is an error (never an empty list). */
export function useOwnerEquityMovements(enabled = true) {
  const me = useCurrentUser();
  const tenantId = me.data?.tenantId ?? null;
  return useQuery({
    queryKey: [...OWNER_EQUITY_KEY, tenantId],
    enabled: enabled && Boolean(tenantId),
    queryFn: async (): Promise<OwnerEquityMovement[]> => {
      const read = (cols: string) => untyped()
        .from("owner_equity_movements")
        .select(cols)
        .order("movement_date", { ascending: false })
        .order("created_at", { ascending: false });
      const base = "id, kind, movement_date, amount, bank_account_id, bank_txn_id, own_line, partner_name, note";
      let { data, error } = await read(`${base}, partner_id`);
      /* R-1847: partner_id comes with migration 20261024190000 — before it, read without the link. */
      if (error && isPartnerIdMissing(error.message)) ({ data, error } = await read(base));
      if (error) throw new Error(error.message);
      return ((data ?? []) as unknown as OwnerEquityMovement[]).map((m) => ({ ...m, partner_id: m.partner_id ?? null }));
    },
  });
}

function invalidateAll(qc: ReturnType<typeof useQueryClient>) {
  qc.invalidateQueries({ queryKey: OWNER_EQUITY_KEY });
  qc.invalidateQueries({ queryKey: ["bank_accounts"] });
  qc.invalidateQueries({ queryKey: ["bank_transactions"] });
  qc.invalidateQueries({ queryKey: ["balance-sheet"] });
}

export interface RecordOwnerEquityInput {
  kind: OwnerEquityKind;
  date: string;
  amount: number;
  accountId: string;
  partner?: string | null;
  note?: string | null;
}

/** Record by hand — adds the bank / Petty Cash line on the chosen account in the same step. */
export function useRecordOwnerEquity() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: RecordOwnerEquityInput) => {
      const { data, error } = await untyped().rpc("record_owner_equity_movement", {
        p_kind: input.kind,
        p_date: input.date,
        p_amount: input.amount,
        p_account_id: input.accountId,
        p_partner: input.partner ?? null,
        p_note: input.note ?? null,
      });
      if (error) throw new Error(error.message);
      return data as string;
    },
    onSuccess: (_d, input) => {
      invalidateAll(qc);
      toast.success(input.kind === "drawings" ? "Drawings recorded — the account balance is lower by this amount" : "Capital recorded — the account balance is higher by this amount");
    },
    onError: (err) => toastError(err, { fallback: "Couldn't record this" }),
  });
}

/** Book a bank line (Reconcile) — as a new entry, or onto an entry recorded by hand earlier. */
export function useBookBankTxnAsOwnerEquity() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: { transactionId: string; partner?: string | null; note?: string | null; movementId?: string | null }) => {
      const { data, error } = await untyped().rpc("book_bank_txn_as_owner_equity", {
        p_txn_id: input.transactionId,
        p_partner: input.partner ?? null,
        p_note: input.note ?? null,
        p_movement_id: input.movementId ?? null,
      });
      if (error) throw new Error(error.message);
      return data as { movement_id: string; kind: OwnerEquityKind; amount: number; replaced_line: string | null };
    },
    onSuccess: (res) => {
      invalidateAll(qc);
      toast.success(res?.replaced_line
        ? "Reconciled — the entry you recorded earlier now uses this bank line (its manual line was removed)"
        : res?.kind === "capital_introduced" ? "Booked as capital introduced & reconciled — not income" : "Booked as drawings & reconciled — not an expense");
    },
    onError: (err) => toastError(err, { fallback: "Couldn't book this line" }),
  });
}

export function useDeleteOwnerEquity() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (id: string) => {
      const { error } = await untyped().rpc("delete_owner_equity_movement", { p_id: id });
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      invalidateAll(qc);
      toast.success("Entry removed");
    },
    onError: (err) => toastError(err, { fallback: "Couldn't remove this entry" }),
  });
}
